"""Explicit PostgreSQL18 NN validity-binding projection and independent66x8 contract; no DB/product calls."""
from pathlib import Path
import json,hashlib,datetime
r=Path.cwd();i=r/'evidence/01_PT/018_NK-OPS-001/input';oldp=i/'2901_master_column_independent_oracle.json';old=json.loads(oldp.read_text());valid="nn.connamespace=c.relnamespace AND nn.conenforced AND nn.convalidated AND NOT nn.condeferrable AND NOT nn.condeferred AND nn.conislocal AND nn.coninhcount=0 AND nn.conparentid=0 AND nn.contypid=0";binding="nn.conrelid=c.oid AND nn.contype='n' AND nn.conkey=ARRAY[a.attnum]";projection="CASE WHEN a.attnotnull THEN EXISTS (SELECT 1 FROM pg_catalog.pg_constraint nn WHERE "+binding+" AND ("+valid+") IS TRUE) AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_constraint nn WHERE "+binding+" AND ("+valid+") IS NOT TRUE) ELSE NOT EXISTS (SELECT 1 FROM pg_catalog.pg_constraint nn WHERE "+binding+") END";needle='a.attgenerated::text FROM pg_catalog.pg_class c';queries=[]
for sql in old['queries']:
 assert sql.count(needle)==1;queries.append(sql.replace(needle,'a.attgenerated::text,'+projection+' FROM pg_catalog.pg_class c'))
vectors=[dict(notNull=True,validity=[True],expected=True),dict(notNull=True,validity=[],expected=False),dict(notNull=True,validity=[False],expected=False),dict(notNull=True,validity=[None],expected=False),dict(notNull=True,validity=[True,False],expected=False),dict(notNull=True,validity=[True,True],expected=True),dict(notNull=False,validity=[],expected=True),dict(notNull=False,validity=[True],expected=False),dict(notNull=False,validity=[False],expected=False)]
for v in vectors:
 statuses=v['validity'];actual=(any(x is True for x in statuses) and all(x is True for x in statuses)) if v['notNull'] else not statuses;assert actual is v['expected']
rows={table:[[str(j+1)]+row+['true'] for j,row in enumerate(cols)] for table,cols in old['tables'].items()};assert sum(map(len,rows.values()))==66 and all(len(row)==8 for table in rows.values() for row in table)
out=dict(actualExit=0,atUTC=datetime.datetime.now(datetime.timezone.utc).isoformat(),previousColumnOracle=dict(path=str(oldp.relative_to(r)),sha256=hashlib.sha256(oldp.read_bytes()).hexdigest()),originalColumnAttributes=old['tables'],eightFieldRows=rows,queries=queries,notNullValidityProjection=projection,validityPredicate=valid,bindingPredicate=binding,independentTruthVectors=vectors,normalColumnGetters=528,targetMixedCatalogGetters=1053,normalField8=True,falseOrSqlNullField8Rejected=True,constraint75StillSevenFields=True,existing66AttributesUnchanged=True,nnNameCardinalityOrOrphansNotQualified=True,actualDatabaseOrSqlEvaluatorOperations=0,productionMethodsCalled=0,technicalSource='https://www.postgresql.org/docs/18/catalog-pg-constraint.html')
(i/'2975_notnull_binding_independent_oracle.json').open('x').write(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print(dict(actualExit=0,columnRows=66,fields=8,columnGetters=528,mixedGetters=1053,truthVectors=9,productTestsExecuted=0))
